import { useCallback, useEffect, useRef, useState } from 'react'
import type { ReactNode } from 'react'
import { ArrowDownRight, ArrowRight, ArrowUpRight, BarChart3, Bell, Check, ChevronDown, ChevronRight, Heart, Home, Info, LayoutGrid, LoaderCircle, MapPin, Minus, Moon, Plus, Search, Settings2, ShieldCheck, ShoppingBag, ShoppingCart, SlidersHorizontal, Sparkles, Sun, Trash2, TrendingDown, UserRound, X, Globe, AlertCircle, ExternalLink, RefreshCw, Send } from 'lucide-react'
import { api, money } from './api'
import Artwork from './Artwork'
import type { Alert, BasketResult, CartEntry, Category, Detail, Product, Store } from './types'

type Page='catalog'|'basket'|'favorites'|'alerts'|'assistant'|'profile'|'history'|'admin'
type Lang='uz'|'ru'
type Profile={region:string;language:Lang;notifications_enabled:boolean;is_admin:boolean;regions:{id:string;name:string}[]}
type AIReply={mode:'ai'|'statistical';answer:string;notice:string;products:Product[];comparison:{product_id:number;name:string;price:number;store:string;url:string}[]}
type AdminOverview={stores:{id:number;name:string;slug:string;active_offers:number;delivery_fee:number;free_delivery_threshold:number|null;adapter_status:string}[];recent_collections:{status:string;at:string;sources:{source:string;items:number;errors:string[]}[]}[]}
const defaultRegions=[['tashkent','Toshkent shahri'],['tashkent-region','Toshkent viloyati'],['andijan','Andijon'],['bukhara','Buxoro'],['fergana','Farg‘ona'],['jizzakh','Jizzax'],['khorezm','Xorazm'],['namangan','Namangan'],['navoiy','Navoiy'],['kashkadarya','Qashqadaryo'],['karakalpakstan','Qoraqalpog‘iston'],['samarkand','Samarqand'],['sirdarya','Sirdaryo'],['surkhandarya','Surxondaryo']]
const dictionary:Record<string,[string,string]>={catalog:['Katalog','Каталог'],basket:['Savatcha','Корзина'],favorites:['Sevimlilar','Избранное'],alerts:['Kuzatuvlar','Отслеживание'],assistant:['Xarid maslahatchisi','Советник по покупкам'],profile:['Profil va sozlamalar','Профиль и настройки'],history:['Narxlar tarixi','История цен'],admin:['Boshqaruv','Управление'],search:['Mahsulot, model yoki brend qidiring…','Товар, модель или бренд…'],all:['Barchasi','Все'],popular:['Siz uchun tanladik','Товары для вас'],cheap:['Eng arzon','Дешевле'],expensive:['Eng qimmat','Дороже'],discount:['Eng ko‘p arzonlashgan','Больше скидка'],newest:['Yangi qo‘shilgan','Новинки'],add:['Savatchaga','В корзину'],details:['Batafsil','Подробнее'],shops:['do‘konda','магазинов'],empty:['Hozircha hech narsa yo‘q','Пока ничего нет'],clear:['Tozalash','Очистить'],close:['Yopish','Закрыть'],apply:['Qo‘llash','Применить'],delivery:['Yetkazish','Доставка'],total:['Jami','Итого'],quantity:['Soni','Количество'],loading:['Yuklanmoqda…','Загрузка…'],retry:['Qayta urinish','Повторить'],demo:['Demo ma’lumotlar','Демонстрационные данные']}
const readCart=():CartEntry[]=>{try{const data=JSON.parse(localStorage.getItem('ea-cart')||'[]');return Array.isArray(data)?data.filter(x=>x?.product?.id && Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=20).slice(0,8):[]}catch{return []}}
const validPage=(s:string|null):s is Page=>['catalog','basket','favorites','alerts','assistant','profile','history','admin'].includes(s||'')

export default function App(){
 const searchParams=new URLSearchParams(window.location.search)
 const [page,setPage]=useState<Page>(validPage(searchParams.get('view'))?searchParams.get('view') as Page:'catalog')
 const [lang,setLang]=useState<Lang>(localStorage.getItem('ea-lang')==='ru'?'ru':'uz')
 const [dark,setDark]=useState(localStorage.getItem('ea-dark')==='true'||(localStorage.getItem('ea-dark')===null&&window.Telegram?.WebApp.colorScheme==='dark'))
 const [region,setRegion]=useState(localStorage.getItem('ea-region')||'tashkent')
 const [regions,setRegions]=useState(defaultRegions),[profileReady,setProfileReady]=useState(false),[isAdmin,setIsAdmin]=useState(false)
 const [notifications,setNotifications]=useState(true),[settingsSaving,setSettingsSaving]=useState(false),[confirmDelete,setConfirmDelete]=useState(false),[deleting,setDeleting]=useState(false)
 const [products,setProducts]=useState<Product[]>([]), [categories,setCategories]=useState<Category[]>([]),[stores,setStores]=useState<Store[]>([])
 const [discountDeals,setDiscountDeals]=useState<Product[]>([])
 const [catalogInfo,setCatalogInfo]=useState<{real_products:number;products_with_offers:number;last_refresh_status:string;last_refresh_at:string|null}|null>(null)
 const [favorites,setFavorites]=useState<Product[]>([]),[alerts,setAlerts]=useState<Alert[]>([])
 const [cart,setCart]=useState<CartEntry[]>(readCart)
 const [query,setQuery]=useState(''),[debounced,setDebounced]=useState(''),[category,setCategory]=useState(''),[sort,setSort]=useState('price_asc')
 const [minPrice,setMinPrice]=useState(''),[maxPrice,setMaxPrice]=useState(''),[store,setStore]=useState(''),[filters,setFilters]=useState(false)
 const [loading,setLoading]=useState(true),[error,setError]=useState(''),[total,setTotal]=useState(0),[listPage,setListPage]=useState(1),[refresh,setRefresh]=useState(0)
 const [selected,setSelected]=useState<Detail|null>(null),[detailLoading,setDetailLoading]=useState(false),[toast,setToast]=useState(''),[target,setTarget]=useState(''),[alertBusy,setAlertBusy]=useState(false)
 const [basket,setBasket]=useState<BasketResult|null>(null),[basketBusy,setBasketBusy]=useState(false)
 const [message,setMessage]=useState(''),[answer,setAnswer]=useState<AIReply|null>(null),[assistantBusy,setAssistantBusy]=useState(false),[chatHistory,setChatHistory]=useState<{role:'user'|'assistant';text:string}[]>([])
 const [adminStats,setAdminStats]=useState<Record<string,number>|null>(null),[adminOverview,setAdminOverview]=useState<AdminOverview|null>(null),[adminBusy,setAdminBusy]=useState(false),[csvFile,setCsvFile]=useState<File|null>(null),[importResult,setImportResult]=useState<Record<string,unknown>|null>(null),[csvText,setCsvText]=useState('')
 const [newCategoryName,setNewCategoryName]=useState(''),[newCategorySlug,setNewCategorySlug]=useState(''),[newCategoryEmoji,setNewCategoryEmoji]=useState('🛍'),[newCategoryParent,setNewCategoryParent]=useState('')
 const [editStore,setEditStore]=useState(''),[editDelivery,setEditDelivery]=useState(''),[editFreeDelivery,setEditFreeDelivery]=useState(''),[editAdapter,setEditAdapter]=useState('disconnected')
 const dialogRef=useRef<HTMLDivElement>(null)
 const profileWrite=useRef<Promise<unknown>>(Promise.resolve()),profileVersion=useRef(0),savedProfile=useRef('')
 const t=(key:string)=>dictionary[key]?.[lang==='ru'?1:0]||key
 const notify=useCallback((msg:string)=>setToast(msg),[])
 const failure=useCallback((e:unknown)=>notify(e instanceof Error?e.message:'Xatolik yuz berdi'),[notify])
 const navigate=(next:Page)=>{setPage(next);setFilters(false);window.scrollTo({top:0,behavior:'smooth'})}
 const favoriteIds=new Set(favorites.map(p=>p.id))
 const cartCount=cart.reduce((s,x)=>s+x.quantity,0)
 useEffect(()=>{window.Telegram?.WebApp.ready();window.Telegram?.WebApp.expand(); document.documentElement.lang=lang},[lang])
 useEffect(()=>{document.documentElement.dataset.theme=dark?'dark':'light';localStorage.setItem('ea-dark',String(dark))},[dark])
 useEffect(()=>{localStorage.setItem('ea-lang',lang)},[lang])
 useEffect(()=>{localStorage.setItem('ea-region',region);setBasket(null)},[region])
 useEffect(()=>{localStorage.setItem('ea-cart',JSON.stringify(cart));setBasket(null)},[cart])
 useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(''),4800);return()=>clearTimeout(timer)},[toast])
 useEffect(()=>{const timer=setTimeout(()=>{setDebounced(query);setListPage(1)},280);return()=>clearTimeout(timer)},[query])
 useEffect(()=>{Promise.all([api<Category[]>('/categories'),api<Store[]>('/stores'),api<Product[]>('/favorites'),api<Alert[]>('/alerts'),api<Profile>('/profile')]).then(([c,s,f,a,p])=>{setCategories(c);setStores(s);setFavorites(f);setAlerts(a);savedProfile.current=JSON.stringify({region:p.region,language:p.language,notifications_enabled:p.notifications_enabled});setRegion(p.region);setLang(p.language);setNotifications(p.notifications_enabled);setRegions(p.regions.map(r=>[r.id,r.name]));setIsAdmin(Boolean(p.is_admin));setProfileReady(true)}).catch(failure)},[failure])
 useEffect(()=>{if(!profileReady)return;const body=JSON.stringify({region,language:lang,notifications_enabled:notifications});if(body===savedProfile.current)return;const version=++profileVersion.current;setSettingsSaving(true);const save=profileWrite.current.catch(()=>undefined).then(()=>api<Profile>('/profile',{method:'PATCH',body}));profileWrite.current=save;void save.then(()=>{savedProfile.current=body}).catch(failure).finally(()=>{if(version===profileVersion.current)setSettingsSaving(false)})},[region,lang,notifications,profileReady,failure])
 useEffect(()=>{api<{real_products:number;products_with_offers:number;last_refresh_status:string;last_refresh_at:string|null}>('/catalog/status').then(setCatalogInfo).catch(()=>{})},[refresh])
 useEffect(()=>{const timer=setInterval(()=>setRefresh(x=>x+1),5*60*1000);return()=>clearInterval(timer)},[])
 useEffect(()=>{api<{items:Product[]}>('/products?sort=discount&page_size=12').then(data=>setDiscountDeals(data.items.filter(p=>p.discount_percent>0&&Boolean(p.image_url)&&Boolean(p.buy_url)))).catch(()=>setDiscountDeals([]))},[refresh])
 useEffect(()=>{let current=true;setLoading(true);setError(''); const params=new URLSearchParams({q:debounced,category,sort,page:String(listPage),page_size:'12'});if(minPrice)params.set('min_price',minPrice);if(maxPrice)params.set('max_price',maxPrice);if(store)params.set('store',store);api<{items:Product[];total:number}>(`/products?${params}`).then(data=>{if(current){setProducts(data.items);setTotal(data.total)}}).catch(e=>{if(current)setError(e.message)}).finally(()=>{if(current)setLoading(false)});return()=>{current=false}},[debounced,category,sort,minPrice,maxPrice,store,listPage,refresh])
 const openProduct=useCallback(async(id:number)=>{setDetailLoading(true);setTarget('');try{await profileWrite.current.catch(()=>undefined);setSelected(await api<Detail>(`/products/${id}`))}catch(e){failure(e)}finally{setDetailLoading(false)}},[failure])
 useEffect(()=>{const product=searchParams.get('product');if(product&&/^\d+$/.test(product))void openProduct(Number(product))},[])
 useEffect(()=>{if(!selected)return;const previous=document.activeElement as HTMLElement|null;dialogRef.current?.focus();const handler=(e:KeyboardEvent)=>{if(e.key==='Escape')setSelected(null);if(e.key==='Tab'&&dialogRef.current){const focusable=dialogRef.current.querySelectorAll<HTMLElement>('button,a,input,select,textarea,[tabindex="0"]');const first=focusable[0],last=focusable[focusable.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}};document.addEventListener('keydown',handler);const oldOverflow=document.body.style.overflow;document.body.style.overflow='hidden';return()=>{document.removeEventListener('keydown',handler);document.body.style.overflow=oldOverflow;previous?.focus()}},[selected])
 const toggleFavorite=async(p:Product)=>{const saved=favoriteIds.has(p.id);try{await api(`/favorites/${p.id}`,{method:saved?'DELETE':'POST'});setFavorites(prev=>saved?prev.filter(x=>x.id!==p.id):[p,...prev]);notify(saved?'Sevimlilardan olib tashlandi':'Sevimlilarga qo‘shildi')}catch(e){failure(e)}}
 const addCart=(p:Product)=>{if(p.min_price===null){notify('Mahsulot uchun mavjud taklif yo‘q');return}if(!cart.some(x=>x.product.id===p.id)&&cart.length>=8){notify('Bir hisobda eng ko‘pi 8 xil mahsulot');return}setCart(prev=>{const found=prev.find(x=>x.product.id===p.id);if(found)return prev.map(x=>x.product.id===p.id?{...x,quantity:Math.min(20,x.quantity+1)}:x);return[...prev,{product:p,quantity:1}]});window.Telegram?.WebApp.HapticFeedback?.impactOccurred('light');notify('Savatchaga qo‘shildi')}
 const saveAlert=async()=>{if(!selected)return;const amount=Number(target);if(!Number.isFinite(amount)||amount<=0){notify('Musbat maqsadli narx kiriting');return}setAlertBusy(true);try{await api('/alerts',{method:'POST',body:JSON.stringify({product_id:selected.id,target_price:amount})});setAlerts(await api<Alert[]>('/alerts'));notify('Kuzatuv saqlandi. Telegram bildirishnomalari bot ulangach ishlaydi.');setTarget('')}catch(e){failure(e)}finally{setAlertBusy(false)}}
 const deleteAlert=async(id:number)=>{try{await api(`/alerts/${id}`,{method:'DELETE'});setAlerts(prev=>prev.filter(a=>a.id!==id));notify('Kuzatuv o‘chirildi')}catch(e){failure(e)}}
 const deleteAccount=async()=>{setDeleting(true);try{await profileWrite.current.catch(()=>undefined);await api('/profile',{method:'DELETE'});['ea-cart','ea-region','ea-lang'].forEach(key=>localStorage.removeItem(key));window.location.reload()}catch(e){failure(e);setDeleting(false)}}
 const toggleAlert=async(a:Alert)=>{try{await api(`/alerts/${a.id}`,{method:'PATCH',body:JSON.stringify({enabled:!a.enabled})});setAlerts(prev=>prev.map(x=>x.id===a.id?{...x,enabled:!a.enabled}:x))}catch(e){failure(e)}}
 const optimize=async()=>{setBasketBusy(true);try{setBasket(await api<BasketResult>('/basket/optimize',{method:'POST',body:JSON.stringify({items:cart.map(x=>({product_id:x.product.id,quantity:x.quantity})),region})}))}catch(e){failure(e)}finally{setBasketBusy(false)}}
 const ask=async(text=message)=>{const prompt=text.trim();if(!prompt||assistantBusy)return;setAssistantBusy(true);try{const past=chatHistory.filter(x=>x.role==='user').slice(-4).map(x=>x.text);const reply=await api<AIReply>('/assistant',{method:'POST',body:JSON.stringify({message:prompt,history:past})});setAnswer(reply);setChatHistory(h=>[...h,{role:'user' as const,text:prompt},{role:'assistant' as const,text:reply.answer}].slice(-12));setMessage('')}catch(e){failure(e)}finally{setAssistantBusy(false)}}
 const loadAdmin=async()=>{if(!isAdmin)return;setAdminBusy(true);try{const [stats,overview]=await Promise.all([api<Record<string,number>>('/admin/stats'),api<AdminOverview>('/admin/overview')]);setAdminStats(stats);setAdminOverview(overview)}catch(e){failure(e)}finally{setAdminBusy(false)}}
 useEffect(()=>{if(page==='admin'&&isAdmin)void loadAdmin()},[page,isAdmin])
 const createCategory=async()=>{if(!isAdmin)return;setAdminBusy(true);try{await api('/admin/categories',{method:'POST',body:JSON.stringify({name:newCategoryName.trim(),slug:newCategorySlug.trim(),emoji:newCategoryEmoji||'🛍',parent_id:newCategoryParent?Number(newCategoryParent):null})});setCategories(await api<Category[]>('/categories'));setNewCategoryName('');setNewCategorySlug('');setNewCategoryParent('');notify('Kategoriya yaratildi');await loadAdmin()}catch(e){failure(e)}finally{setAdminBusy(false)}}
 const chooseStore=(id:string)=>{setEditStore(id);const found=stores.find(st=>String(st.id)===id);if(found){setEditDelivery(String(found.delivery_fee));setEditFreeDelivery(found.free_delivery_threshold===null?'':String(found.free_delivery_threshold));setEditAdapter(found.adapter_status)}}
 const saveStore=async()=>{if(!isAdmin||!editStore)return;setAdminBusy(true);try{await api('/admin/stores/'+encodeURIComponent(editStore),{method:'PUT',body:JSON.stringify({delivery_fee:Number(editDelivery),free_delivery_threshold:editFreeDelivery?Number(editFreeDelivery):null,adapter_status:editAdapter})});setStores(await api<Store[]>('/stores'));notify('Do‘kon sozlamasi yangilandi');await loadAdmin()}catch(e){failure(e)}finally{setAdminBusy(false)}}
 const importCsv=async(commit=false)=>{if(!csvFile||!isAdmin)return;setAdminBusy(true);try{const text=commit?csvText:await csvFile.text();setCsvText(text);setImportResult(await api('/admin/import',{method:'POST',body:JSON.stringify({csv_text:text,commit})}));if(commit){setRefresh(x=>x+1);await loadAdmin()}}catch(e){failure(e)}finally{setAdminBusy(false)}}

 function ProductCard({product:p}:{product:Product}){return <article className="product-card"><div className="product-visual"><button className="art-button" aria-label={`${p.name}: ${t('details')}`} onClick={()=>void openProduct(p.id)}><Artwork product={p}/></button>{p.discount_percent>0&&<span className="discount-tag">−{p.discount_percent}%</span>}<button className={`icon-button favorite-button ${favoriteIds.has(p.id)?'active':''}`} aria-label={favoriteIds.has(p.id)?'Sevimlilardan o‘chirish':'Sevimlilarga qo‘shish'} onClick={()=>void toggleFavorite(p)}><Heart size={18} fill={favoriteIds.has(p.id)?'currentColor':'none'}/></button></div><div className="product-body"><div className="product-meta"><span>{p.brand}</span><span className="store-count"><span className="tiny-dot"/>{p.store_count} {t('shops')}</span></div><button className="product-title" onClick={()=>void openProduct(p.id)}>{p.name}</button><p className="product-attributes">{Object.entries(p.attributes).slice(0,2).map(([,v])=>String(v)).join(' · ')||p.category_name}</p><div className="product-price">{money(p.min_price)} <span>so‘m</span>{p.old_price&&p.old_price>Number(p.min_price)&&<small style={{display:"block",fontSize:12,textDecoration:"line-through",opacity:.6}}>{money(p.old_price)} so‘m</small>}</div><div className="product-bottom"><span className="lowest"><TrendingDown size={13}/> {p.min_price===null?'Yangilangan taklif yo‘q':'Eng past taklif'}</span><button disabled={p.min_price===null} className="mini-cart" aria-label={`${p.name} ${t('add')}`} onClick={()=>addCart(p)}><Plus size={18}/></button></div>{p.buy_url&&<a className="offer-external" href={p.buy_url} target="_blank" rel="noopener noreferrer" style={{display:'inline-flex',gap:5,alignItems:'center',fontWeight:700,marginTop:8}}>🛍 {p.buy_store||'Do‘kon'}dan olish <ExternalLink size={13}/></a>}</div></article>}
 function Empty({children,icon=<ShoppingBag size={30}/>}:{children:ReactNode;icon?:ReactNode}){return <div className="empty-state"><div className="empty-icon">{icon}</div><h3>{t('empty')}</h3><p>{children}</p><button className="button primary" onClick={()=>navigate('catalog')}>{t('catalog')} <ArrowRight size={16}/></button></div>}
 function ProductGrid({items}:{items:Product[]}){return <div className="product-grid">{items.map(p=><ProductCard key={p.id} product={p}/>)}</div>}
 function InfoBox({children}:{children:ReactNode}){return <div className="info-box"><Info size={17}/><span>{children}</span></div>}
 const navItems:[Page,ReactNode][]=[['catalog',<Home size={21}/>],['favorites',<Heart size={21}/>],['basket',<ShoppingCart size={21}/>],['alerts',<Bell size={21}/>],['profile',<UserRound size={21}/>]]

 return <div className="app-shell antialiased">
 <aside className="sidebar"><a className="brand" href="#" aria-label="Engarzon bosh sahifa" title="Engarzon bosh sahifa" onClick={e=>{e.preventDefault();navigate('catalog')}}><span className="brand-symbol"><ShoppingCart size={23}/><span/></span><span>eng<span className="brand-blue">arzon</span><small>AQLLI XARID YORDAMCHISI</small></span></a><div className="sidebar-label">ASOSIY MENYU</div><nav>{navItems.filter(([id])=>id!=='profile').map(([id,icon])=><button key={id} aria-label={t(id)} title={t(id)} aria-current={page===id?'page':undefined} className={`side-link ${page===id?'selected':''}`} onClick={()=>navigate(id)}>{icon}<span>{t(id)}</span>{id==='basket'&&cartCount>0&&<b>{cartCount}</b>}{id==='alerts'&&alerts.length>0&&<b>{alerts.length}</b>}</button>)}</nav><div className="sidebar-label second-label">AQLLI VOSITALAR</div><nav>{([['assistant',<Sparkles size={21}/>],['history',<BarChart3 size={21}/>]] as [Page,ReactNode][]).map(([id,icon])=><button key={id} aria-label={t(id)} title={t(id)} aria-current={page===id?'page':undefined} className={`side-link ${page===id?'selected':''}`} onClick={()=>navigate(id)}>{icon}<span>{t(id)}</span>{id==='assistant'&&<span className="new-pill">NEW</span>}</button>)}</nav><div className="sidebar-bottom"><div className="save-card"><div className="save-card-icon"><ShieldCheck size={22}/></div><b>Xaridingizni aqlli qiling</b><p>Mahsulotlarni ko‘ring.<br/>Xarid havolasini oling.</p><button onClick={()=>navigate('basket')}>Savatchani hisoblash <ArrowUpRight size={15}/></button></div><button aria-label={t('profile')} title={t('profile')} aria-current={page==='profile'?'page':undefined} className={`side-link ${page==='profile'?'selected':''}`} onClick={()=>navigate('profile')}><UserRound size={21}/><span>{t('profile')}</span></button>{isAdmin&&<button className="side-link" onClick={()=>navigate('admin')}><ShieldCheck size={21}/><span>Admin panel</span></button>}<div className="version"><span className="tiny-dot"/> MVP 1.0 · Jonli katalog</div></div></aside>
 <div className="main-shell"><header className="topbar"><button type="button" className="mobile-brand" aria-label="Engarzon bosh sahifa" onClick={()=>navigate('catalog')}><span className="brand-symbol"><ShoppingCart size={20}/></span><b>engarzon</b></button><div className="desktop-breadcrumb">Xush kelibsiz! <span>Qulay xarid shu yerdan boshlanadi.</span></div><div className="topbar-actions"><label className="region-picker"><MapPin size={16}/><select aria-label="Yetkazish hududi" value={region} onChange={e=>setRegion(e.target.value)}>{regions.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select><ChevronDown size={13}/></label><button className="icon-button theme-toggle" aria-label={dark?'Yorug‘ mavzu':'Qorong‘i mavzu'} onClick={()=>setDark(x=>!x)}>{dark?<Sun size={19}/>:<Moon size={19}/>}</button>{isAdmin&&<button className="icon-button admin-header-button" aria-label="Admin boshqaruvini ochish" title="Admin boshqaruvi" onClick={()=>navigate('admin')}><ShieldCheck size={20}/></button>}<button className="profile-avatar" aria-label={t('profile')} onClick={()=>navigate('profile')}>EA</button></div></header>
 <main className="main-content"><div className="demo-notice"><span className="notice-pill">KATALOG</span><p>Haqiqiy mahsulotlar katalogi har 2 soatda yangilanadi. Narx va mavjudlikni xarid qilishdan oldin do‘konda tekshiring.</p><Info size={16}/></div>
 {(page==='catalog'||page==='history')&&<>
 <div className="page-title-row"><div><div className="eyebrow">HAR BIR XARIDDA KO‘PROQ TEJANG</div><h1>{page==='history'?t('history'):'Yaxshi narxni topish oson.'}</h1><p>{page==='history'?'Mahsulotni tanlab, saqlangan narxlar tarixi va xarid tavsiyasini ko‘ring.':'Sevimli mahsulotlaringiz va xarid havolalari — bir joyda.'}</p></div><span className="catalog-stamp"><ShieldCheck size={16}/> Manbasi ochiq narxlar</span></div>
 <div className="search-row"><label className="search-box"><Search size={21}/><input value={query} onChange={e=>setQuery(e.target.value)} placeholder={t('search')} aria-label={t('search')}/>{query&&<button className="icon-button" aria-label={t('clear')} onClick={()=>setQuery('')}><X size={17}/></button>}<kbd>⌕</kbd></label><button aria-label="Filtrlar" title="Filtrlar" aria-expanded={filters} className={`button filter-button ${filters?'is-active':''}`} onClick={()=>setFilters(x=>!x)}><SlidersHorizontal size={18}/><span>Filtrlar</span>{(minPrice||maxPrice||store)&&<span className="filter-dot"/>}</button></div>
 {filters&&<div className="filter-panel"><label>Minimum narx<input inputMode="numeric" type="number" min="0" value={minPrice} onChange={e=>{setMinPrice(e.target.value);setListPage(1)}} placeholder="0 so‘m"/></label><label>Maksimum narx<input inputMode="numeric" type="number" min="0" value={maxPrice} onChange={e=>{setMaxPrice(e.target.value);setListPage(1)}} placeholder="Cheklanmagan"/></label><label>Do‘kon<select value={store} onChange={e=>{setStore(e.target.value);setListPage(1)}}><option value="">Barcha do‘konlar</option>{stores.map(s=><option value={s.id} key={s.id}>{s.name}{s.is_demo?' · Yetkazish tasdiqlanmagan':''}</option>)}</select></label><button className="text-button" onClick={()=>{setMinPrice('');setMaxPrice('');setStore('');setCategory('');setListPage(1)}}>{t('clear')}</button></div>}
 {!debounced&&!category&&page==='catalog'&&<section className="hero-grid"><div className="hero-main"><div className="hero-copy"><span className="hero-pill"><Sparkles size={13}/> TURLI TOIFADAGI MAHSULOTLAR</span><h2>Turli mahsulotlar.<br/><span>Qulay katalog.</span></h2><p>Uy-ro‘zg‘or, sport, kitob va texnika.<br/>Mahsulot havolalari bir joyda.</p><button className="hero-button" onClick={()=>{setSort('discount');document.getElementById('products-heading')?.scrollIntoView({behavior:'smooth'})}}>Takliflarni ko‘rish <ArrowRight size={17}/></button></div><div className="hero-product"><div className="hero-orbit one"/><div className="hero-orbit two"/><div className="hero-generic-photo" aria-hidden="true"><ShoppingBag size={88}/></div><div className="floating-saving"><span><TrendingDown size={17}/></span><div><small>Xarid havolalari</small><b>Oqilona tanlang</b></div><Check size={17}/></div></div><div className="hero-dots"><i/><i/><i/></div></div><button className="basket-promo" onClick={()=>navigate('basket')}><span className="promo-icon"><ShoppingBag size={25}/><span className="spark-dot">✦</span></span><span className="promo-label">ENG ARZON SAVATCHA</span><h3>Ro‘yxat sizdan,<br/>hisob-kitob bizdan.</h3><p>Bir nechta mahsulotni yetkazish bilan eng arzon kombinatsiyada oling.</p><span className="promo-action">Savatcha tuzish <ArrowRight size={17}/></span><div className="promo-line"/></button></section>}
 <section className="categories"><div className="section-head"><h2><LayoutGrid size={18}/> Kategoriyalar</h2>{category&&<button className="text-button" onClick={()=>{setCategory('');setListPage(1)}}>Barchasi <ArrowRight size={14}/></button>}</div><div className="category-row"><button className={`category-card ${!category?'chosen':''}`} onClick={()=>{setCategory('');setListPage(1)}}><span className="category-emoji all-category"><LayoutGrid size={23}/></span><span>{t('all')}</span></button>{categories.filter(c=>!c.parent_id).map(c=><button key={c.id} className={`category-card ${category===c.slug?'chosen':''}`} onClick={()=>{setCategory(c.slug);setListPage(1)}}><span className="category-emoji">{c.emoji}</span><span>{c.name}</span></button>)}</div></section>
 {page==='catalog'&&!debounced&&!category&&discountDeals.length>0&&<section className="products-section"><div className="section-head"><div><h2>📉 Haqiqiy kuzatilgan chegirmalar</h2><p>Oldingi kuzatilgan narxga nisbatan arzonlashgan mahsulotlar</p></div></div><ProductGrid items={discountDeals.slice(0,8)}/></section>}
 <section className="products-section"><div className="section-head product-section-head"><div><h2 id="products-heading">{debounced?`“${debounced}” bo‘yicha natijalar`:category?categories.find(c=>c.slug===category)?.name:t('popular')} {!loading&&<span className="count-pill">{total}</span>}</h2><p>Yetkazish xarajati va narx tarixini mahsulot ichida ko‘ring</p></div><label className="sort-select"><span>Saralash:</span><select value={sort} aria-label="Saralash" onChange={e=>{setSort(e.target.value);setListPage(1)}}><option value="price_asc">{t('cheap')}</option><option value="price_desc">{t('expensive')}</option><option value="discount">{t('discount')}</option><option value="newest">{t('newest')}</option></select><ChevronDown size={14}/></label></div>{error?<div className="error-state"><AlertCircle/><p>{error}</p><button className="button primary" onClick={()=>setRefresh(x=>x+1)}><RefreshCw size={16}/>{t('retry')}</button></div>:loading?<div className="product-grid" aria-label={t('loading')}>{Array.from({length:8},(_,i)=><div className="skeleton-card" key={i}><div/><span/><span/><b/></div>)}</div>:products.length?<ProductGrid items={products}/>:<Empty icon={<Search size={30}/>}>{!debounced&&!category&&catalogInfo?.real_products===0?'Haqiqiy mahsulotlar hali yig‘ilmagan. Katalog har 2 soatda yangilanadi. Asaxiy, OLX va mavjud tasdiqlangan manbalardan takliflar kutilyapti.': 'Hozir mos haqiqiy taklif topilmadi. Qidiruv yoki filtrlarni o‘zgartiring.'}</Empty>}{total>12&&!loading&&<div className="pagination"><button className="button" disabled={listPage===1} onClick={()=>setListPage(x=>x-1)}>Oldingi</button><span>{listPage} / {Math.ceil(total/12)}</span><button className="button" disabled={listPage>=Math.ceil(total/12)} onClick={()=>setListPage(x=>x+1)}>Keyingi <ChevronRight size={16}/></button></div>}</section>
 <div className="trust-strip"><div><ShieldCheck size={22}/><span><b>Manbasi ko‘rsatilgan</b><small>Faqat manbadan kuzatilgan takliflar</small></span></div><div><Bell size={22}/><span><b>Narxni kuzating</b><small>Maqsadli narxni o‘zingiz belgilang</small></span></div><div><ShoppingCart size={22}/><span><b>Yakuniy xarajat</b><small>Yetkazish ham hisobga olinadi</small></span></div></div>
 </>}

 {page==='favorites'&&<><PageHeading title={t('favorites')} subtitle="Yoqtirgan mahsulotlaringiz bir joyda. Xarid havolalarini oching." icon={<Heart/>}/>{favorites.length?<ProductGrid items={favorites}/>:<Empty icon={<Heart size={30}/>}>Mahsulotdagi yurak belgisini bosing va uni shu yerda saqlang.</Empty>}</>}

 {page==='basket'&&<><PageHeading title="Eng arzon savatcha" subtitle="Mahsulotlar va har bir do‘konning yetkazish haqini birgalikda hisoblaymiz." icon={<ShoppingCart/>}/><InfoBox>Hisoblash {cart.some(x=>x.product.is_demo)?'demo':'katalogdagi yangilangan'} takliflar asosida amalga oshiriladi. Bir do‘konning yetkazish haqi bir marta qo‘shiladi. Hudud bo‘yicha haq ma’lum bo‘lmasa, natija bu haqda ogohlantiradi.</InfoBox>{!cart.length?<Empty>Kamida bitta mahsulotni savatchaga qo‘shing. Masalan, 5 ta mahsulot uchun eng arzon do‘konlar kombinatsiyasini topamiz.</Empty>:<div className="basket-layout"><div className="panel cart-panel"><div className="panel-title"><h3>Xarid ro‘yxati <span>{cart.length} xil mahsulot</span></h3><button className="text-button danger" onClick={()=>setCart([])}>{t('clear')}</button></div>{cart.map(({product:p,quantity})=><div className="cart-row" key={p.id}><button aria-label={`${p.name}: ${t('details')}`} className="cart-art" onClick={()=>void openProduct(p.id)}><Artwork product={p}/></button><div className="cart-description"><button onClick={()=>void openProduct(p.id)}>{p.name}</button><small>{money(p.min_price)} so‘mdan</small><b>{money((p.min_price||0)*quantity)} so‘m</b></div><div className="quantity-stepper"><button aria-label="Kamaytirish" disabled={quantity<=1} onClick={()=>setCart(prev=>prev.map(x=>x.product.id===p.id?{...x,quantity:quantity-1}:x))}><Minus size={14}/></button><span>{quantity}</span><button aria-label="Ko‘paytirish" disabled={quantity>=20} onClick={()=>setCart(prev=>prev.map(x=>x.product.id===p.id?{...x,quantity:quantity+1}:x))}><Plus size={14}/></button></div><button className="icon-button danger" aria-label={`${p.name} o‘chirish`} onClick={()=>setCart(prev=>prev.filter(x=>x.product.id!==p.id))}><Trash2 size={17}/></button></div>)}<button className="button add-more" onClick={()=>navigate('catalog')}><Plus size={17}/> Yana mahsulot qo‘shish</button></div><div className="panel basket-summary"><span className="eyebrow">AQLLI HISOB-KITOB</span><h3>Qancha tejash mumkin?</h3><p>Yetkazishni qo‘shgan holda eng arzon mavjud takliflar kombinatsiyasini topamiz.</p><label className="field-label">Yetkazish hududi<select value={region} onChange={e=>setRegion(e.target.value)}>{regions.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></label><button className="button primary full-width" disabled={basketBusy} onClick={()=>void optimize()}>{basketBusy?<LoaderCircle className="spinning" size={18}/>:<Sparkles size={18}/>} Hisoblash</button><small className="muted">Maksimum 8 xil mahsulot · Katalog hisobi</small></div>{basket&&<div className="basket-result panel"><div className="result-heading"><div><span className="eyebrow">ENG ARZON KOMBINATSIYA · KATALOG</span><h3>{money(basket.total)} <small>so‘m</small></h3></div>{basket.savings>0&&<span className="savings-badge"><TrendingDown size={17}/>{money(basket.savings)} so‘m tejaladi</span>}</div>{basket.stores.map(s=><div className="store-allocation" key={s.store_id}><div className="allocation-head"><span className="store-initial">{s.store_name[0]}</span><b>{s.store_name}</b><span>{money(s.total)} so‘m</span></div>{basket.items.filter(i=>i.store_id===s.store_id).map(i=><div className="allocation-item" key={i.product_id}><span>{i.name} × {i.quantity}</span><b>{money(i.subtotal)} so‘m</b></div>)}<div className="allocation-item delivery-line"><span>{t('delivery')}</span><span>{s.delivery_fee===0?'Bepul':`${money(s.delivery_fee)} so‘m`}</span></div></div>)}<div className="totals-row"><span>Mahsulotlar</span><b>{money(basket.subtotal)} so‘m</b></div><div className="totals-row"><span>Jami yetkazish</span><b>{money(basket.delivery_total)} so‘m</b></div><div className="totals-row final"><span>Yakuniy summa</span><b>{money(basket.total)} so‘m</b></div>{basket.single_store_total!==null&&<p className="muted">Barchasini bitta do‘kondan olish: {money(basket.single_store_total)} so‘m.</p>}{basket.warnings?.map((w,i)=><InfoBox key={i}>{w}</InfoBox>)}</div>}</div>}</>}

 {page==='alerts'&&<><PageHeading title="Narx kuzatuvlari" subtitle="Narx siz belgilagan qiymatga tushganda xabar olish uchun kuzatuv yarating." icon={<Bell/>}/><InfoBox>Kuzatuvlar bazada saqlanadi. Telegram xabarlari bot tokeni va ishchi jarayon sozlangandan keyin yuboriladi. Narxlarni do‘konning xarid sahifasida tekshiring.</InfoBox>{alerts.length?<div className="alerts-list">{alerts.map(a=><div className="panel alert-row" key={a.id}><span className="alert-icon"><Bell size={22}/></span><div><button className="inline-title" onClick={()=>void openProduct(a.product_id)}>{a.product_name}</button><p>Maqsadli narx: <b>{money(a.target_price)} so‘m</b></p><small className="status-tag">{a.enabled?'Faol kuzatuv':'O‘chirilgan'}</small></div><button className={`toggle ${a.enabled?'on':''}`} role="switch" aria-checked={a.enabled} aria-label={`${a.product_name} kuzatuvini ${a.enabled?'o‘chirish':'yoqish'}`} onClick={()=>void toggleAlert(a)}><span/></button><button className="icon-button danger" aria-label="Kuzatuvni o‘chirish" onClick={()=>void deleteAlert(a.id)}><Trash2 size={18}/></button></div>)}</div>:<Empty icon={<Bell size={30}/>}>Mahsulotni oching va “Narx tushsa xabar bering” bo‘limida maqsadli narx kiriting.</Empty>}</>}

 {page==='assistant'&&<><PageHeading title="🤖 AI xarid yordamchisi" subtitle="Eng arzon mahsulotlarni toping, narxlarni suhbat orqali solishtiring." icon={<Sparkles/>}/>
 <div className="assistant-layout">
 <div className="panel assistant-panel">
  <span className="assistant-orb"><Sparkles size={29}/></span><h2>Qaysi mahsulotni qidiryapsiz?</h2>
  <p>Oddiy o‘zbek tilida yozing. Masalan, “3 million so‘mgacha telefon topib ber” yoki “Samsung bilan Redmi’ni solishtir”. Faqat haqiqiy katalogdagi narxlar ishlatiladi.</p>
  <div className="mode-label"><span className="tiny-dot"/>{answer?.mode==='ai'?'AI faol · Katalogdan tekshirilgan narxlar':answer?.mode==='statistical'?'Katalog bo‘yicha yordamchi · AI kaliti ulanmagan bo‘lishi mumkin':'Narxlar katalogdan olinadi · AI ulanishi serverga bog‘liq'}</div>
  <div className="prompt-examples">{['3 million so‘mgacha telefon topib ber','Samsung va Redmi telefonlarini solishtir','Eng arzon noutbukni ko‘rsat','Eng arzon changyutgich qaysi?'].map(text=><button key={text} disabled={assistantBusy} onClick={()=>void ask(text)}>{text}<ArrowUpRight size={15}/></button>)}</div>
  {chatHistory.length>0&&<div className="ai-chat-log" aria-live="polite">{chatHistory.map((item,i)=><div key={i} className={item.role==='user'?'ai-message ai-user':'ai-message ai-bot'}><small>{item.role==='user'?'Siz':'Xarid yordamchisi'}</small><p>{item.text}</p></div>)}</div>}
  <form className="assistant-input" onSubmit={e=>{e.preventDefault();void ask()}}><input value={message} onChange={e=>setMessage(e.target.value)} placeholder="Masalan: Redmi va Samsung solishtir" aria-label="Maslahatchiga so‘rov" maxLength={1000}/><button aria-label="Yuborish" disabled={assistantBusy||!message.trim()}>{assistantBusy?<LoaderCircle size={19} className="spinning"/>:<Send size={19}/>}</button></form>
  <p className="muted ai-disclaimer">AI javobi va haqiqiy narxlar alohida tekshiriladi. Yakuniy narx, chegirma va ombor holatini do‘kon sahifasidan tekshiring.</p>
 </div>
 <div className="panel advice-principles"><h3>U qanday yordam beradi?</h3><div><Search size={21}/><p><b>Mahsulot topadi</b><span>Mahsulot nomi, brend yoki byudjet bo‘yicha yangilangan katalogdan qidiradi.</span></p></div><div><BarChart3 size={21}/><p><b>Narxlarni solishtiradi</b><span>Mahsulotlarni birma-bir, haqiqiy do‘kon va narxlar bilan ko‘rsatadi.</span></p></div><div><ShieldCheck size={21}/><p><b>Haqiqiy ma’lumot</b><span>AI o‘zi narx, aksiya yoki sotib olish havolasini yaratmaydi.</span></p></div></div>
 {answer&&<div className="assistant-answer">
  <div className="panel answer-text"><span><Sparkles size={18}/>{answer.mode==='ai'?'AI izohi':'Katalog yordamchisi'} · Haqiqiy takliflar</span><p>{answer.answer}</p><small className="muted">{answer.notice}</small></div>
  {answer.comparison?.length>0&&<div className="panel ai-compare"><h3>Topilgan narxlar</h3><div className="ai-compare-list">{answer.comparison.map(row=><div className="ai-price-row" key={row.product_id}><button className="inline-title" onClick={()=>void openProduct(row.product_id)}>{row.name}</button><span className="muted">{row.store}</span><b>{money(row.price)} so‘m</b><a href={row.url} className="offer-external" target="_blank" rel="noopener noreferrer">Do‘konda ko‘rish <ExternalLink size={14}/></a></div>)}</div></div>}
  {answer.products?.length>0&&<ProductGrid items={answer.products}/>}
 </div>}
 </div></>}

 {page==='profile'&&<><PageHeading title={t('profile')} subtitle="Til, ko‘rinish va yetkazish hududini o‘zingizga moslang." icon={<UserRound/>}/><div className="profile-grid"><div className="panel profile-card"><span className="large-avatar">EA</span><h3>{window.Telegram?.WebApp.initData?'Telegram foydalanuvchisi':'Mehmon'}</h3><span className="mode-label">{window.Telegram?.WebApp.initData?'Telegram sessiyasi':'Mahalliy sinov sessiyasi'}</span><p>Haqiqiy profilingizni ulash uchun Mini App’ni sozlangan Telegram botidan oching.</p><div className="profile-stats"><div><b>{favorites.length}</b><span>Sevimli</span></div><div><b>{alerts.length}</b><span>Kuzatuv</span></div><div><b>{cart.length}</b><span>Savatchada</span></div></div></div><div className="panel settings-panel"><h3><Settings2 size={19}/> Shaxsiy sozlamalar</h3><div className="setting-row"><span><Globe size={19}/> Ilova tili</span><select aria-label="Ilova tili" value={lang} onChange={e=>setLang(e.target.value as Lang)}><option value="uz">O‘zbekcha</option><option value="ru">Русский</option></select></div><div className="setting-row"><span><Moon size={19}/> Qorong‘i mavzu</span><button className={`toggle ${dark?'on':''}`} role="switch" aria-checked={dark} aria-label="Qorong‘i mavzu" onClick={()=>setDark(x=>!x)}><span/></button></div><div className="setting-row"><span><Bell size={19}/> Bildirishnomalar</span><button className={`toggle ${notifications?'on':''}`} role="switch" aria-checked={notifications} aria-label="Telegram bildirishnomalari" disabled={!profileReady} onClick={()=>setNotifications(x=>!x)}><span/></button></div><div className="setting-row"><span><MapPin size={19}/> Hudud</span><select aria-label="Profil hududi" value={region} onChange={e=>setRegion(e.target.value)}>{regions.map(([id,name])=><option key={id} value={id}>{name}</option>)}</select></div>{isAdmin&&<button className="setting-row settings-link" onClick={()=>navigate('admin')}><span><ShieldCheck size={19}/> Admin boshqaruvi</span><ChevronRight size={16}/></button>}<InfoBox>Premium, to‘lovlar va referral bonuslari bu MVPda ulanmagan. Obuna yoki bonus faollashgani haqida xabar berilmaydi.</InfoBox><p className="muted">{settingsSaving?'Sozlamalar saqlanmoqda…':'Til, hudud va bildirishnoma holati serverda saqlanadi. Ko‘rinish ushbu brauzerda saqlanadi.'} O‘zbekcha va ruscha asosiy navigatsiya mavjud; katalog ma’lumotlari manba tilida ko‘rsatiladi.</p><button className="text-button danger" onClick={()=>setConfirmDelete(x=>!x)}>Hisob ma’lumotlarini o‘chirish</button>{confirmDelete&&<div className="info-box"><div><p>Sevimlilar, kuzatuvlar va qidiruv tarixingiz o‘chiriladi. Qayta kirishda yangi bo‘sh hisob yaratiladi.</p><button className="button danger" disabled={deleting} onClick={()=>void deleteAccount()}>{deleting?'O‘chirilmoqda…':'Ha, ma’lumotlarimni o‘chirish'}</button><button className="button" disabled={deleting} onClick={()=>setConfirmDelete(false)}>Bekor qilish</button></div></div>}</div></div><div className="panel connections-panel"><h3>Do‘kon ulanishlari</h3><p className="muted">Hamkorlik katalogi yoki ruxsatli API ulangach jonli takliflar ishlaydi.</p>{stores.map(s=><div className="connection-row" key={s.id}><span className="store-initial">{s.name[0]}</span><b>{s.name}</b><span className="disconnected">{s.adapter_status==='public'?'Ochiq katalog':s.adapter_status==='csv'?'CSV katalog':s.adapter_status==='partner'?'Hamkor katalog':'Ulanmagan'}{s.is_demo?' · Yetkazish tasdiqlanmagan':''}</span></div>)}</div></>}

 {page==='admin'&&<><PageHeading title="🛡 Admin boshqaruvi" subtitle="Faqat Telegram orqali tasdiqlangan administratorga ochiq." icon={<ShieldCheck/>}/>
 {!profileReady?<InfoBox>Telegram bot orqali Mini App’ni oching. Profil tekshirilmoqda.</InfoBox>:!isAdmin?<div className="panel admin-panel"><h3>⛔ Admin huquqi talab qilinadi</h3><p>Ushbu sahifaga faqat egasining tasdiqlangan Telegram akkaunti orqali kiriladi. Botga /myid yuborib ID’ni tekshirishingiz mumkin.</p></div>:<div className="admin-dashboard">
 <div className="panel admin-panel"><div className="admin-panel-top"><div><h3>Boshqaruv markazi</h3><p className="muted">Telegram akkauntingiz tasdiqlangan. Maxfiy token kiritish shart emas.</p></div><button className="button primary" disabled={adminBusy} onClick={()=>void loadAdmin()}>{adminBusy?<LoaderCircle size={17} className="spinning"/>:<RefreshCw size={17}/>} Yangilash</button></div>
 {adminStats?<div className="stats-grid">{([['products','Mahsulotlar'],['offers','Takliflar'],['users','Foydalanuvchilar'],['stores','Do‘konlar'],['categories','Kategoriyalar'],['alerts','Narx kuzatuvlari'],['imports','Importlar']] as [string,string][]).map(([key,label])=><div key={key}><span>{label}</span><b>{Number(adminStats[key]??0).toLocaleString('uz-UZ')}</b></div>)}</div>:<p className="muted">{adminBusy?'Statistika yuklanmoqda…':'Ma’lumotni yuklash uchun Yangilash tugmasini bosing.'}</p>}
 </div>
 <div className="panel admin-panel"><h3>Manbalar holati</h3><p className="muted">Oxirgi yig‘ishdagi mahsulotlar soni va xatolar. Noto‘g‘ri narx yoki bo‘sh ma’lumot qo‘shilmaydi.</p>
 {adminOverview?.recent_collections?.[0]?<><p className="muted">Oxirgi yangilanish: {new Date(adminOverview.recent_collections[0].at).toLocaleString('uz-UZ')} · {adminOverview.recent_collections[0].status}</p><div className="admin-source-list">{adminOverview.recent_collections[0].sources.map((src,i)=><div className="admin-source-row" key={src.source+i}><b>{src.source.toUpperCase()}</b><span>{src.items} ta mahsulot</span><small>{src.errors.length?src.errors.join(', '):'Xatolik yo‘q'}</small></div>)}</div></>:<p className="muted">Yig‘ish tarixi hali mavjud emas.</p>}
 </div>
 <div className="panel admin-panel"><h3>Yangi kategoriya yaratish</h3><form className="admin-form" onSubmit={e=>{e.preventDefault();void createCategory()}}><label>Nomi<input required minLength={2} maxLength={100} value={newCategoryName} onChange={e=>{setNewCategoryName(e.target.value);setNewCategorySlug(e.target.value.toLowerCase().normalize('NFKD').replace(/[^a-z0-9 ]/g,'').trim().replace(/ +/g,'-'))}} placeholder="Masalan: Gul va sovg‘alar"/></label><label>Slug<input required pattern="[a-z0-9-]+" minLength={2} maxLength={100} value={newCategorySlug} onChange={e=>setNewCategorySlug(e.target.value)} placeholder="gul-sovgalar"/></label><label>Belgisi<input maxLength={16} value={newCategoryEmoji} onChange={e=>setNewCategoryEmoji(e.target.value)}/></label><label>Ota kategoriya<select value={newCategoryParent} onChange={e=>setNewCategoryParent(e.target.value)}><option value="">Asosiy kategoriya</option>{categories.filter(c=>!c.parent_id).map(c=><option key={c.id} value={c.id}>{c.name}</option>)}</select></label><button className="button primary" disabled={adminBusy||!newCategoryName.trim()||!newCategorySlug.trim()}>Kategoriya qo‘shish</button></form></div>
 <div className="panel admin-panel"><h3>Do‘kon sozlamalari</h3><p className="muted">Yetkazib berish haqini faqat do‘kon ma’lumotini tasdiqlagan bo‘lsangiz yangilang. Bu yerda do‘kon API’sini yoqish yoki cheklovni aylanib o‘tish mumkin emas.</p><form className="admin-form" onSubmit={e=>{e.preventDefault();void saveStore()}}><label>Do‘kon<select required value={editStore} onChange={e=>chooseStore(e.target.value)}><option value="">Do‘kon tanlang</option>{stores.map(st=><option key={st.id} value={st.id}>{st.name}</option>)}</select></label><label>Yetkazish narxi (so‘m)<input required type="number" min="0" max="1000000000" value={editDelivery} onChange={e=>setEditDelivery(e.target.value)}/></label><label>Bepul yetkazish chegarasi (ixtiyoriy)<input type="number" min="1" value={editFreeDelivery} onChange={e=>setEditFreeDelivery(e.target.value)}/></label><label>Ulanish turi<select value={editAdapter} onChange={e=>setEditAdapter(e.target.value)}><option value="disconnected">Ulanmagan</option><option value="public">Ochiq katalog</option><option value="csv">CSV katalog</option><option value="partner">Hamkor API</option></select></label><button className="button primary" disabled={adminBusy||!editStore||editDelivery===''||Number(editDelivery)<0}>O‘zgarishlarni saqlash</button></form>
 {adminOverview?.stores&&<div className="admin-source-list">{adminOverview.stores.map(st=><div className="admin-source-row" key={st.id}><b>{st.name}</b><span>{st.active_offers} ta mavjud taklif</span><small>{st.adapter_status}</small></div>)}</div>}
 </div>
 <div className="panel admin-panel"><h3>CSV orqali mahsulot import qilish</h3><p className="muted">Avval faylni tekshiring, keyin tasdiqlang. Faqat ruxsatli manbalardan olingan haqiqiy mahsulotlar.</p><input type="file" accept=".csv,text/csv" onChange={e=>{setCsvFile(e.target.files?.[0]||null);setImportResult(null);setCsvText('')}}/><button className="button primary" disabled={!csvFile||adminBusy} onClick={()=>void importCsv(false)}>CSVni tekshirish</button>{importResult?.ok===true&&importResult?.committed!==true&&<button className="button primary" disabled={adminBusy} onClick={()=>void importCsv(true)}>Importni tasdiqlash</button>}{importResult&&<pre className="admin-json">{JSON.stringify(importResult,null,2)}</pre>}</div>
 </div>}</>}

 <footer className="page-footer"><span>© {new Date().getFullYear()} Eng Arzon</span><span>Aqlli xarid. Ochiq ma’lumot. <span className="footer-demo">Kuzatilgan narxlar</span></span></footer>
 </main></div>
 <nav className="bottom-nav">{navItems.map(([id,icon])=><button key={id} aria-label={t(id)} title={t(id)} aria-current={page===id?'page':undefined} className={page===id?'selected':''} onClick={()=>navigate(id)}><span>{icon}{id==='basket'&&cartCount>0&&<b>{cartCount}</b>}</span><small>{id==='profile'?(lang==='ru'?'Профиль':'Profil'):t(id)}</small></button>)}</nav>
 {toast&&<div className="toast" role="status"><Info size={18}/><span>{toast}</span><button aria-label={t('close')} onClick={()=>setToast('')}><X size={15}/></button></div>}
 {detailLoading&&<div className="detail-loading" aria-label={t('loading')}><LoaderCircle className="spinning" size={34}/></div>}
 {selected&&<div className="modal-backdrop" onClick={e=>{if(e.target===e.currentTarget)setSelected(null)}}><div className="product-dialog" ref={dialogRef} role="dialog" aria-modal="true" aria-label={selected.name} tabIndex={-1}><div className="dialog-top"><span><ShoppingBag size={17}/> Mahsulot tafsilotlari </span><button className="icon-button" aria-label={t('close')} onClick={()=>setSelected(null)}><X size={22}/></button></div><div className="detail-intro"><div className="detail-image"><Artwork product={selected}/><span>{selected.image_url?'Manbadagi mahsulot rasmi':'Manbada rasm mavjud emas'}</span></div><div className="detail-info"><span className="eyebrow">{selected.brand} · {selected.category_name}</span><h2>{selected.name}</h2><p>{selected.description}</p><div className="detail-attributes">{Object.entries(selected.attributes).map(([k,v])=><span key={k}>{k}: <b>{String(v)}</b></span>)}</div><div className="detail-price-label">Kuzatilgan mahsulot narxi</div><div className="detail-price">{money(selected.min_price)} <small>so‘m</small></div><div className="detail-actions"><button className="button primary" onClick={()=>addCart(selected)}><ShoppingCart size={17}/>{t('add')}</button><button className={`button ${favoriteIds.has(selected.id)?'favorite-active':''}`} aria-label="Sevimlilar" onClick={()=>void toggleFavorite(selected)}><Heart size={18} fill={favoriteIds.has(selected.id)?'currentColor':'none'}/></button></div></div></div><section className="offers-section"><h3>Mahsulotni do‘konda ko‘rish</h3><p>Haqiqiy narx va mavjudlikni sotuvchining sahifasida tekshiring.</p>{selected.shipping_notice&&<InfoBox>{selected.shipping_notice}</InfoBox>}{selected.buy_url?<a className="button primary offer-external" href={selected.buy_url} target="_blank" rel="noopener noreferrer">{selected.buy_store||"Do‘kon"}dan sotib olish <ExternalLink size={16}/></a>:<InfoBox>Hozircha tekshirilgan xarid havolasi yo‘q.</InfoBox>}</section><section className="history-section"><div className="section-head"><h3><BarChart3 size={18}/> Narxlar tarixi</h3><span className="subtle-pill">Saqlangan kuzatuvlar</span></div><PriceChart history={selected.history}/><div className={`insight-card ${selected.insight.verdict}`}><span className="insight-icon">{selected.insight.verdict==='buy'?<TrendingDown/>:selected.insight.verdict==='wait'?<ArrowDownRight/>:<Info/>}</span><div><span className="eyebrow">STATISTIK TAHLIL</span><h4>{selected.insight.title}</h4><p>{selected.insight.explanation}</p><small>{selected.insight.sample_count} kuzatuv · {selected.insight.span_days} kun. Kelajak narxi kafolatlanmaydi.</small></div></div></section><section className="alert-create"><div><Bell size={22}/><div><h3>Narx tushsa xabar bering</h3><p>Maqsadli narxni belgilang. Kuzatuv bazada saqlanadi.</p></div></div><div className="alert-create-form"><input type="number" min="1" inputMode="numeric" value={target} onChange={e=>setTarget(e.target.value)} placeholder="Maqsadli narx, so‘m" aria-label="Maqsadli narx"/><button className="button primary" disabled={alertBusy||!target} onClick={()=>void saveAlert()}>{alertBusy?<LoaderCircle size={16} className="spinning"/>:<Bell size={16}/>} Kuzatish</button></div></section></div></div>}
 </div>
}

function PageHeading({title,subtitle,icon}:{title:string;subtitle:string;icon:ReactNode}){return <div className="feature-page-heading"><span>{icon}</span><div><h1>{title}</h1><p>{subtitle}</p></div></div>}
function PriceChart({history}:{history:Detail['history']}){
 const [period,setPeriod]=useState(30)
 const latest=Date.parse(new Date().toISOString().slice(0,10)+'T00:00:00Z')
 const filtered=history.filter(h=>new Date(h.date).getTime()>=latest-(period-1)*86400000&&new Date(h.date).getTime()<=latest).sort((a,b)=>new Date(a.date).getTime()-new Date(b.date).getTime())
 const prices=filtered.map(h=>h.price),min=Math.min(...prices),max=Math.max(...prices),range=Math.max(max-min,max*.02,1),pad=range*.2
 const start=filtered.length?new Date(filtered[0].date).getTime():latest
 const end=filtered.length?new Date(filtered[filtered.length-1].date).getTime():latest
 const x=(i:number)=>filtered.length<=1?450:60+(new Date(filtered[i].date).getTime()-start)/Math.max(end-start,1)*790
 const y=(p:number)=>190-(p-min+pad)/(range+2*pad)*150
 const points=filtered.map((h,i)=>`${x(i)},${y(h.price)}`).join(' ')
 return <><div className="chart-periods">{[7,30,90,180].map(d=><button key={d} className={period===d?'active':''} onClick={()=>setPeriod(d)}>{d} kun</button>)}</div>{filtered.length<2?<div className="no-history"><BarChart3 size={25}/><p>Bu davr uchun kamida ikkita kuzatuv kerak. Grafik uydirilmaydi.</p></div>:<div className="price-chart"><svg viewBox="0 0 900 240" role="img" aria-label={`So‘nggi ${period} kunlik saqlangan narx tarixi`}><defs><linearGradient id="priceArea" x1="0" y1="0" x2="0" y2="1"><stop stopColor="#1b61ee" stopOpacity=".2"/><stop offset="1" stopColor="#1b61ee" stopOpacity="0"/></linearGradient></defs>{[0,.5,1].map((ratio,i)=>{const price=min+range*ratio;return <g key={i}><line x1="60" y1={y(price)} x2="855" y2={y(price)} stroke="currentColor" opacity=".08" strokeDasharray="5 5"/><text x="0" y={y(price)+4} fill="currentColor" opacity=".5" fontSize="12">{price>=1000000?`${(price/1000000).toFixed(1)} mln`:money(price)}</text></g>})}<path d={`M ${x(0)},205 L ${points.replaceAll(' ',' L ')} L ${x(filtered.length-1)},205 Z`} fill="url(#priceArea)"/><polyline points={points} fill="none" stroke="#1b61ee" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>{filtered.map((h,i)=><circle key={i} cx={x(i)} cy={y(h.price)} r="3" fill="#1b61ee"><title>{new Date(h.date).toLocaleDateString('uz-UZ')}: {money(h.price)} so‘m</title></circle>)}{[0,Math.floor((filtered.length-1)/2),filtered.length-1].filter((v,i,a)=>a.indexOf(v)===i).map(i=><text key={i} x={x(i)} y="233" fill="currentColor" opacity=".5" fontSize="12" textAnchor="middle">{new Date(filtered[i].date).toLocaleDateString('uz-UZ',{day:'numeric',month:'short'})}</text>)}</svg><p className="chart-note">Faqat saqlangan {filtered.length} ta kuzatuv ko‘rsatilgan. Yo‘q davrlar uchun narx yaratilmagan.</p></div>}</>
}
